CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE admission_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,name text NOT NULL,academic_year text NOT NULL,timezone text NOT NULL DEFAULT 'Asia/Jakarta',status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','closed','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(school_id,academic_year,name));
CREATE INDEX admission_periods_school_idx ON admission_periods(school_id,status);
CREATE TABLE admission_waves(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),name text NOT NULL,registration_start timestamptz NOT NULL,registration_end timestamptz NOT NULL,payment_end timestamptz,test_start timestamptz,test_end timestamptz,announcement_at timestamptz,reregistration_end timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,CHECK(registration_end>registration_start),UNIQUE(period_id,name));
CREATE INDEX admission_waves_school_idx ON admission_waves(school_id,period_id);
CREATE TABLE admission_tracks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),code text NOT NULL,name text NOT NULL,quota integer NOT NULL CHECK(quota>=0),eligibility_config jsonb NOT NULL DEFAULT '{}',waitlist_policy jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(period_id,code));

CREATE TABLE guardians(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,name text NOT NULL DEFAULT '',identity_user_id uuid,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE guardian_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,guardian_id uuid NOT NULL REFERENCES guardians(id),kind text NOT NULL CHECK(kind IN('email','phone')),normalized_value text NOT NULL,verified_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,kind,normalized_value));
CREATE TABLE otp_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,contact_kind text NOT NULL CHECK(contact_kind IN('email','phone')),contact_value text NOT NULL,purpose text NOT NULL,code_hash text NOT NULL,attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL,expires_at timestamptz NOT NULL,resend_after timestamptz NOT NULL,used_at timestamptz,request_ip_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX otp_lookup_idx ON otp_challenges(school_id,contact_kind,contact_value,purpose,created_at DESC);
CREATE TABLE applicants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,guardian_id uuid NOT NULL REFERENCES guardians(id),full_name text NOT NULL,nisn text,birth_date date,birth_place text,gender text,source text,profile jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX applicants_guardian_idx ON applicants(school_id,guardian_id);
CREATE TABLE applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,applicant_id uuid NOT NULL REFERENCES applicants(id),period_id uuid NOT NULL REFERENCES admission_periods(id),wave_id uuid NOT NULL REFERENCES admission_waves(id),track_id uuid NOT NULL REFERENCES admission_tracks(id),registration_number text NOT NULL,status text NOT NULL DEFAULT 'draft',version integer NOT NULL DEFAULT 1,answers jsonb NOT NULL DEFAULT '{}',submitted_snapshot jsonb,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,registration_number),UNIQUE(applicant_id,period_id));
CREATE INDEX applications_queue_idx ON applications(school_id,status,period_id,wave_id,track_id);
CREATE TABLE application_state_events(id bigserial PRIMARY KEY,school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),from_status text,to_status text NOT NULL,actor_type text NOT NULL,actor_id text NOT NULL,reason text,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE form_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),version integer NOT NULL,schema jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(period_id,version));
CREATE TABLE document_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),track_id uuid REFERENCES admission_tracks(id),code text NOT NULL,name text NOT NULL,required boolean NOT NULL DEFAULT true,allowed_mimes text[] NOT NULL DEFAULT ARRAY['application/pdf','image/jpeg','image/png'],max_bytes bigint NOT NULL CHECK(max_bytes>0),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(period_id,code,version));
CREATE TABLE application_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),requirement_id uuid NOT NULL REFERENCES document_requirements(id),object_key text NOT NULL,mime text NOT NULL,size_bytes bigint NOT NULL,sha256 text NOT NULL,scan_status text NOT NULL DEFAULT 'pending' CHECK(scan_status IN('pending','clean','infected','failed')),uploaded_by text NOT NULL,locked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,requirement_id));
CREATE TABLE document_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,document_id uuid NOT NULL REFERENCES application_documents(id),status text NOT NULL CHECK(status IN('accepted','correction','rejected')),notes text,reviewer_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE fee_schemes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),track_id uuid REFERENCES admission_tracks(id),name text NOT NULL,revision integer NOT NULL,status text NOT NULL DEFAULT 'draft',currency text NOT NULL DEFAULT 'IDR' CHECK(currency='IDR'),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(period_id,track_id,revision));
CREATE TABLE fee_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,fee_scheme_id uuid NOT NULL REFERENCES fee_schemes(id),code text NOT NULL,name text NOT NULL,amount_idr bigint NOT NULL CHECK(amount_idr>=0),discountable boolean NOT NULL DEFAULT true,UNIQUE(fee_scheme_id,code));
CREATE TABLE installment_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,fee_scheme_id uuid NOT NULL REFERENCES fee_schemes(id),sequence integer NOT NULL,description text NOT NULL,amount_idr bigint NOT NULL CHECK(amount_idr>=0),due_at timestamptz NOT NULL,UNIQUE(fee_scheme_id,sequence));
CREATE TABLE discount_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),name text NOT NULL,kind text NOT NULL CHECK(kind IN('fixed','percent')),value bigint NOT NULL CHECK(value>=0),cap_idr bigint,priority integer NOT NULL,conditions jsonb NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE discount_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),code_hash text NOT NULL,kind text NOT NULL CHECK(kind IN('fixed','percent')),value bigint NOT NULL,cap_idr bigint,priority integer NOT NULL,usage_limit integer NOT NULL DEFAULT 1,used_count integer NOT NULL DEFAULT 0,valid_from timestamptz NOT NULL,valid_until timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,code_hash));
CREATE TABLE manual_discounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),kind text NOT NULL CHECK(kind IN('fixed','percent')),value bigint NOT NULL,cap_idr bigint,priority integer NOT NULL,reason text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE charges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),revision integer NOT NULL,fee_scheme_id uuid NOT NULL REFERENCES fee_schemes(id),gross_idr bigint NOT NULL,discount_idr bigint NOT NULL,net_idr bigint NOT NULL,items_snapshot jsonb NOT NULL,discount_snapshot jsonb NOT NULL,finalized_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,revision),CHECK(gross_idr>=discount_idr AND net_idr=gross_idr-discount_idr));
CREATE TABLE discount_applications(id bigserial PRIMARY KEY,school_id uuid NOT NULL,charge_id uuid NOT NULL REFERENCES charges(id),sequence integer NOT NULL,source text NOT NULL,source_id text NOT NULL,base_before_idr bigint NOT NULL,requested_idr bigint NOT NULL,applied_idr bigint NOT NULL,base_after_idr bigint NOT NULL,snapshot jsonb NOT NULL,UNIQUE(charge_id,sequence));
CREATE TABLE payment_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),charge_id uuid NOT NULL REFERENCES charges(id),amount_idr bigint NOT NULL CHECK(amount_idr>0),object_key text NOT NULL,mime text NOT NULL,size_bytes bigint NOT NULL,sha256 text NOT NULL,status text NOT NULL DEFAULT 'submitted',uploader_type text NOT NULL,uploader_id text NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,idempotency_key));
CREATE TABLE payment_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,payment_id uuid NOT NULL REFERENCES payment_submissions(id),action text NOT NULL CHECK(action IN('pending_review','verified','rejected')),reviewer_id text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,payment_id uuid NOT NULL REFERENCES payment_submissions(id),installment_id uuid REFERENCES installment_plans(id),amount_idr bigint NOT NULL CHECK(amount_idr>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_reversals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,payment_id uuid NOT NULL REFERENCES payment_submissions(id),amount_idr bigint NOT NULL CHECK(amount_idr>0),reason text NOT NULL,actor_id text NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,idempotency_key));

CREATE TABLE selection_components(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),code text NOT NULL,name text NOT NULL,source text NOT NULL,required boolean NOT NULL DEFAULT true,max_score bigint NOT NULL DEFAULT 10000,UNIQUE(period_id,code));
CREATE TABLE selection_formula_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),wave_id uuid NOT NULL REFERENCES admission_waves(id),track_id uuid NOT NULL REFERENCES admission_tracks(id),version integer NOT NULL,formula jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',checksum text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(wave_id,track_id,version));
CREATE TABLE component_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),component_id uuid NOT NULL REFERENCES selection_components(id),score bigint NOT NULL,final boolean NOT NULL DEFAULT false,source_ref text,entered_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,component_id));
CREATE TABLE ranking_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL,wave_id uuid NOT NULL,track_id uuid NOT NULL,formula_version_id uuid NOT NULL REFERENCES selection_formula_versions(id),version integer NOT NULL,input_checksum text NOT NULL,status text NOT NULL DEFAULT 'draft',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(wave_id,track_id,version));
CREATE TABLE ranking_entries(id bigserial PRIMARY KEY,school_id uuid NOT NULL,ranking_run_id uuid NOT NULL REFERENCES ranking_runs(id),application_id uuid NOT NULL REFERENCES applications(id),rank integer NOT NULL,total_score bigint NOT NULL,scores_snapshot jsonb NOT NULL,recommendation text NOT NULL CHECK(recommendation IN('accepted','waitlist')),UNIQUE(ranking_run_id,application_id),UNIQUE(ranking_run_id,rank));
CREATE TABLE decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),ranking_entry_id bigint REFERENCES ranking_entries(id),decision text NOT NULL CHECK(decision IN('offered','waitlisted','rejected')),override boolean NOT NULL DEFAULT false,reason text,actor_id text NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,version),CHECK(NOT override OR reason IS NOT NULL));

CREATE TABLE reregistration_checklists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,period_id uuid NOT NULL REFERENCES admission_periods(id),name text NOT NULL,min_payment_idr bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reregistration_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,checklist_id uuid NOT NULL REFERENCES reregistration_checklists(id),code text NOT NULL,label text NOT NULL,required boolean NOT NULL DEFAULT true,UNIQUE(checklist_id,code));
CREATE TABLE application_reregistration_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),item_id uuid NOT NULL REFERENCES reregistration_items(id),completed_at timestamptz,completed_by text,notes text,UNIQUE(application_id,item_id));
CREATE TABLE student_conversions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES applications(id),idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'pending',guardian_step jsonb NOT NULL DEFAULT '{}',student_step jsonb NOT NULL DEFAULT '{}',link_step jsonb NOT NULL DEFAULT '{}',enrollment_step jsonb NOT NULL DEFAULT '{}',identity_guardian_id text,student_user_id text,enrollment_id text,last_error text,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id),UNIQUE(school_id,idempotency_key));
CREATE TABLE audit_events(id bigserial PRIMARY KEY,school_id uuid NOT NULL,aggregate_type text NOT NULL,aggregate_id text NOT NULL,action text NOT NULL,actor_type text NOT NULL,actor_id text NOT NULL,before_data jsonb,after_data jsonb,reason text,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_lookup_idx ON audit_events(school_id,aggregate_type,aggregate_id,created_at DESC);
